      text: "9B8\nc\na/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/tests/transfers.test.ts\n\n7\n7\n6import test, { after, before } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { spawn, type ChildProcess } from 'node:child_process';\nimport { randomUUID } from 'node:crypto';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nconst temp = fs.mkdtempSync(path.join(os.tmpdir(), 'banana-transfers-'));\nprocess.env.DATA_DIR = temp;\nprocess.env.BANK_DATA_DIR = temp;\nprocess.env.BANK_PORT = '4101';\nprocess.env.BANK_URL = 'http://127.0.0.1:4101';\nconst { transferMoney } = await import('../src/banking/actions');\nconst { resolveIntent } = await import('../src/banking/resolve');\nconst { appDb, closeAppDb } = await import('../src/db');\nconst { bankDb, closeBankDb } = await import('../simulator/db');\nconst { seedBank } = await import('../simulator/seed');\nconst { setScenario } = await import('../simulator/bank');\nconst input = {\n  fromAccountId: 'acc-lucia',\n  toAccountId: 'acc-bruno',\n  amountCents: 1000,\n  concept: 'Test',\n};\nconst ctx = (intentId: string, userId = 'lucia', extra: Record<string, unknown> = {}) => ({\n  userId,\n  conversationId: null,\n  runId: randomUUID(),\n  intentId,\n  ...extra,\n});\nasync function transferConfirmed(intentId: string, userId: string, args = input) {\n  const proposal = (await transferMoney(ctx(intentId, userId), args)) as any;\n  assert.equal(proposal.status, 'requires_confirmation');\n  return transferMoney(\n    ctx(intentId, userId, { approvalId: proposal.approvalId, confirmedBy: 'click' }),\n    args,\n  ) as Promise<any>;\n}\nconst operations = () =>\n  bankDb().prepare(\"SELECT * FROM operations WHERE concept='Test'\").all() as any[];\nconst balance = (id: string) =>\n  (\n    bankDb().prepare('SELECT balanceCents FROM accounts WHERE id=?').get(id) as {\n      balanceCents: number;\n    }\n  ).balanceCents;\nconst intent = (id: string) => appDb().prepare('SELECT * FROM intents WHERE id=?').get(id) as any;\nconst resetApp = () => appDb().exec('DELETE FROM approvals; DELETE FROM intents;');\nlet bank: ChildProcess;\nbefore(async () => {\n  bank = spawn(process.execPath, ['--import', 'tsx', 'simulator/server.ts'], {\n    env: process.env,\n    stdio: 'ignore',\n  });\n  for (let i = 0; i < 60; i++) {\n    try {\n      const r = await fetch(`${process.env.BANK_URL}/health`, {\n        signal: AbortSignal.timeout(500),\n      });\n      if (r.ok) return;\n    } catch {}\n    await new Promise((r) => setTimeout(r, 250));\n  }\n  throw new Error('The bank could not be started.');\n});\nfor (const scenario of ['lost-response', 'slow-response'] as const)\n  test(`${scenario}: one transfer commits exactly once`, async () => {\n    seedBank();\n    resetApp();\n    setScenario(scenario);\n    const intentId = randomUUID(),\n      before = balance('acc-lucia');\n    const result = await transferConfirmed(intentId, 'lucia');\n    assert.equal(result.status, 'completed');\n    assert.equal(operations().length, 1);\n    assert.equal(balance('acc-lucia'), before - 1000);\n    assert.equal(intent(intentId).status, 'completed');\n    assert.equal(intent(intentId).bank_reference, operations()[0].reference);\n  });\ntest('reject-before: retry reuses the same reference', async () => {\n  seedBank();\n  resetApp();\n  setScenario('reject-before');\n  const intentId = randomUUID();\n  const result = await transferConfirmed(intentId, 'lucia');\n  assert.equal(result.status, 'completed');\n  assert.equal(operations().length, 1);\n  assert.equal(intent(intentId).bank_reference, operations()[0].reference);\n});\ntest('read-unavailable: unknown resolves against the ledger without re-sending', async () => {\n  seedBank();\n  resetApp();\n  setScenario('read-unavailable');\n  const intentId = randomUUID();\n  const proposal = (await transferMoney(ctx(intentId), input)) as any;\n  const first = await transferMoney(\n    ctx(intentId, 'lucia', { approvalId: proposal.approvalId, confirmedBy: 'click' }),\n    input,\n  );\n  assert.equal(first.status, 'unknown');\n  assert.equal(operations().length, 1);\n  assert.equal(intent(intentId).status, 'unknown');\n  assert.equal(intent(intentId).bank_reference, operations()[0].reference);\n  const resolved = await resolveIntent('lucia', intentId);\n  assert.equal(resolved.status, 'completed');\n  assert.equal(operations().length, 1);\n  assert.equal(intent(intentId).status, 'completed');\n  assert.ok(\n    (\n      appDb().prepare(\"SELECT COUNT(*) n FROM events WHERE kind='transfer.resolved'\").get() as {\n        n: number;\n      }\n    ).n > 0,\n  );\n  const replay = await transferMoney(ctx(intentId), input);\n  assert.equal(replay.status, 'completed');\n  assert.equal(operations().length, 1);\n});\ntest('a completed intent replays its recorded operation', async () => {\n  seedBank();\n  resetApp();\n  setScenario('normal');\n  const intentId = randomUUID();\n  const first = await transferConfirmed(intentId, 'lucia');\n  const again = (await transferMoney(ctx(intentId), input)) as any;\n  assert.equal(again.status, 'completed');\n  assert.equal(again.replay, true);\n  assert.equal(again.operation.id, first.operation.id);\n  assert.equal(operations().length, 1);\n});\ntest('intermittent seed 17: three transfers complete with three operations', async () => {\n  seedBank();\n  resetApp();\n  setScenario('intermittent', 17);\n  const before = balance('acc-lucia');\n  for (let i = 0; i < 3; i++) {\n    const result = await transferConfirmed(randomUUID(), 'lucia');\n    assert.equal(result.status, 'completed');\n  }\n  assert.equal(operations().length, 3);\n  assert.equal(balance('acc-lucia'), before - 3000);\n});\ntest('insufficient funds fail without new operations', async () => {\n  seedBank();\n  resetApp();\n  setScenario('normal');\n  const intentId = randomUUID();\n  const result = await transferConfirmed(intentId, 'diego', {\n    ...input,\n    fromAccountId: 'acc-diego',\n    amountCents: 10000,\n  });\n  assert.equal(result.status, 'failed');\n  assert.equal(operations().length, 0);\n  assert.equal(intent(intentId).status, 'failed');\n});\ntest('unknown stays unknown while the bank is down', async () => {\n  seedBank();\n  resetApp();\n  const intentId = randomUUID();\n  appDb()\n    .prepare('INSERT INTO intents VALUES(?,?,?,?,?,?,?,?,?,?)')\n    .run(\n      intentId,\n      'lucia',\n      null,\n      randomUUID(),\n      JSON.stringify(input),\n      'unknown',\n      'ref-gone',\n      null,\n      'pending',\n      new Date().toISOString(),\n    );\n  bank.kill('SIGTERM');\n  await Promise.race([\n    new Promise((r) => bank.once('exit', r)),\n    new Promise((r) => setTimeout(r, 5000)),\n  ]);\n  const result = await resolveIntent('lucia', intentId);\n  assert.equal(result.status, 'unknown');\n  assert.equal(intent(intentId).status, 'unknown');\n});\nafter(async () => {\n  if (bank.exitCode === null) {\n    bank.kill('SIGTERM');\n    await Promise.race([\n      new Promise((r) => bank.once('exit', r)),\n      new Promise((r) => setTimeout(r, 5000)),\n    ]);\n    if (bank.exitCode === null) bank.kill('SIGKILL');\n  }\n  closeAppDb();\n  closeBankDb();\n  fs.rmSync(temp, { recursive: true, force: true });\n});\n \n\n(6:a/Users/miguelgarglez/Developer/hackathon-tdots/challenge-banana-candidate/tests/transfers.test.tsB\n\nVcall-1726a723-9441-4863-9991-957ba08cf633-20\nfc_b8b8b194-ea58-933b-b8ac-3e75b5074229_2",
